{
  "name": "@betterspec/opencode",
  "version": "0.1.0",
  "description": "OpenCode plugin for betterspec — multi-agent spec-driven development",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "bin": {
    "betterspec-opencode": "./dist/setup.js"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "scripts": {
    "build": "tsup",
    "dev": "tsup --watch",
    "test": "vitest run",
    "clean": "rm -rf dist"
  },
  "files": ["dist", "agents", "skills"],
  "license": "MIT",
  "peerDependencies": {
    "@betterspec/core": ">=0.3.0"
  },
  "peerDependenciesMeta": {
    "@betterspec/core": {
      "optional": true
    }
  },
  "devDependencies": {
    "@betterspec/core": "^0.3.0",
    "@opencode-ai/plugin": "^1.2.24",
    "@types/node": "^22.0.0",
    "tsup": "^8.4.0",
    "typescript": "^5.8.0",
    "vitest": "^3.1.0"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/betterspec/opencode-betterspec.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "betterspec",
    "spec-driven",
    "multi-agent",
    "ai-development"
  ],
  "dependencies": {
    "@clack/prompts": "^1.1.0",
    "chalk": "^5.6.2"
  }
}
